<?php require "../config.php";$page_title="Register";$err="";if($_SERVER["REQUEST_METHOD"]==="POST"){$h=password_hash($_POST["password"],PASSWORD_DEFAULT);$s=$conn->prepare("INSERT INTO users(name,email,password,role) VALUES(?,?,?,'student')");$s->bind_param("sss",$_POST["name"],$_POST["email"],$h);if($s->execute()){$_SESSION["user_id"]=$s->insert_id;$_SESSION["user"]=["name"=>$_POST["name"],"email"=>$_POST["email"]];$_SESSION["role"]="student";header("Location: /cgua/student/");exit;}$err="Email already exists.";}require "../includes/header.php";?><section class="section portal-shell"><div class="container col-lg-5"><div class="dashboard-card"><div class="eyebrow">Join CGUA</div><h2>Create account</h2><?php if($err):?><div class="alert alert-danger"><?=$err?></div><?php endif;?><form method="post"><input class="form-control my-2" name="name" placeholder="Full name" required><input class="form-control my-2" name="email" type="email" placeholder="Email" required><input class="form-control my-2" name="password" type="password" placeholder="Password" required><button class="btn btn-adventure w-100 rounded-pill mt-2">Register</button></form></div></div></section><?php require "../includes/footer.php";?>